<?php
/* Caminho: pages/assinatura.php */
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';$pdo=arc_db();arc_ensure_user_schema($pdo);
if(!arc_is_user()){header('Location: '.arc_workspace_base_url().'index.php',true,303);exit;}
$uid=(int)arc_user_id();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  arc_verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='cancel_renewal'){
   $pdo->prepare('UPDATE '.arc_table('billing_subscriptions').' SET cancel_at_period_end=1 WHERE account_id=?')->execute([$uid]);$notice='Renovação cancelada. O período já pago será mantido.';
  }else throw new RuntimeException('Ação inválida.');
  $_SESSION['arc_flash']=$notice;header('Location: '.arc_workspace_base_url().'pages/assinatura.php',true,303);exit;
 }catch(RuntimeException $e){$error=$e instanceof PDOException?'Serviço indisponível. Verifique os registros do servidor.':$e->getMessage();}catch(Throwable $e){error_log('Assinatura: '.$e->getMessage());$error='Não foi possível concluir. Nenhum pagamento foi confirmado.';}
}
$plans=$pdo->query('SELECT * FROM '.arc_table('billing_plans').' WHERE enabled=1 ORDER BY price_cents,id')->fetchAll();$policy=arc_billing_policy($pdo,$uid);$usage=arc_billing_usage($pdo,$uid);$sub=arc_billing_subscription($pdo,$uid);
$ARCPageTitle='Planos e cobrança';$ARCActiveNav='billing';require dirname(__DIR__).'/includes/header.php';require dirname(__DIR__).'/includes/sidebar.php';
?>
<main class="app-main"><div class="page-content arc-service">
<header class="arc-service-heading"><div><h1>Planos</h1><p>Escolha a capacidade da sua operação.</p></div><a class="arc-icon-action" href="pages/cobrancas.php" aria-label="Histórico de cobranças" title="Histórico de cobranças"><i class="fa fa-history" aria-hidden="true"></i></a><?php if($sub):?><button type="button" class="arc-icon-action" data-open-dialog="current-subscription" title="Sua assinatura" aria-label="Sua assinatura"><i class="fa fa-user-circle" aria-hidden="true"></i></button><?php endif;?><span class="arc-service-pill" title="<?=arc_h($policy['name'])?>"><?=$policy['active']?'Acesso ativo':'Regularizar acesso'?></span></header>
<?php if($error):?><p class="arc-service-error" role="alert"><?=arc_h($error)?></p><?php endif;?>
<div class="arc-service-metrics"><?php foreach(['networks'=>'Redes ativas','gestores'=>'Gestores aprovados','seats'=>'Técnicos adicionais'] as $k=>$label):?><article><small><?=arc_h($label)?></small><strong><?=$usage[$k]?> <small>/ <?=(int)$policy[$k.'_limit']?:'sem limite'?></small></strong></article><?php endforeach;?></div>
<?php if($sub):?><dialog id="current-subscription" class="arc-service-dialog"><header class="arc-service-heading"><h2>Sua assinatura</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p><?=arc_h($sub['name'])?> · <?=arc_money((int)$sub['price_cents'])?> a cada 30 dias. Período até <?=arc_h(arc_when($sub['period_end']))?>.</p><p>A renovação gera uma nova cobrança. Não há débito automático em cartão.</p><form method="post"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="cancel_renewal"><button class="button" <?=$sub['cancel_at_period_end']?'disabled':''?>><?=$sub['cancel_at_period_end']?'Renovação cancelada':'Cancelar próxima renovação'?></button></form></dialog><?php endif;?>
<div class="arc-service-plans arc-catalog"><?php foreach($plans as $p):?><article class="arc-service-card arc-plan-card"><h2><?=arc_h($p['name'])?></h2><p class="arc-plan-price"><?=arc_money((int)$p['price_cents'])?><small>/30 dias</small></p><div class="arc-plan-capacity"><span title="Redes"><i class="fa fa-sitemap" aria-hidden="true"></i> <?=(int)$p['networks_limit']?:'∞'?></span><span title="Computadores"><i class="fa fa-desktop" aria-hidden="true"></i> <?=(int)$p['gestores_limit']?:'∞'?></span><span title="Equipe"><i class="fa fa-users" aria-hidden="true"></i> <?=(int)$p['seats_limit']?:'∞'?></span></div><button type="button" class="arc-icon-action arc-plan-open" data-open-dialog="plan-<?=(int)$p['id']?>" aria-label="Ver e escolher o plano <?=arc_h($p['name'])?>" title="Ver plano"><i class="fa fa-arrow-right" aria-hidden="true"></i></button><dialog id="plan-<?=(int)$p['id']?>" class="arc-service-dialog"><header class="arc-service-heading"><h2><?=arc_h($p['name'])?> · <?=arc_money((int)$p['price_cents'])?></h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><ul><li><?=(int)$p['networks_limit']?:'Ilimitadas'?> redes</li><li><?=(int)$p['gestores_limit']?:'Ilimitados'?> gestores</li><li><?=(int)$p['seats_limit']?:'Ilimitados'?> técnicos adicionais</li><li>Chamados, histórico e suporte remoto</li></ul><form method="post" action="pages/checkout.php" class="arc-service-form"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="start"><input type="hidden" name="plan_id" value="<?=(int)$p['id']?>"><label>Pagamento<select name="provider" required><option value="">Selecione</option><?php foreach(['mercadopago'=>'Mercado Pago','asaas'=>'Asaas','pix'=>'Pix manual'] as $k=>$label):if(arc_billing_setting($pdo,$k.'_enabled')==='1'):?><option value="<?=$k?>"><?=$label?></option><?php endif;endforeach;?></select></label><button class="button primary" aria-label="Continuar para pagamento" title="Continuar para pagamento"><i class="fa fa-arrow-right" aria-hidden="true"></i><span class="arc-action-label">Continuar para pagamento</span></button></form></dialog></article><?php endforeach;?></div>

</div></main>
